import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

type Mode = { kind: 'none' } | { kind: 'create' } | { kind: 'detail'; id: number } | { kind: 'edit'; id: number } | { kind: 'confirm'; id: number };

export default function FnSfr02306Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [confirmed, setConfirmed] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [mode, setMode] = useState<Mode>({ kind: 'none' });

  const list = useData<Page>(
    () => call<Page>('GET', '/retirement-pays', role, undefined, { ...applied, page, size: SIZE }),
    [JSON.stringify(applied), page],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/retirement-pays', role, undefined, { confirmed: 'false', page: 0, size: 1 }),
    [],
  );

  const search = () => {
    setPage(0);
    setApplied({ employeeId, confirmed });
  };
  const reset = () => {
    setEmployeeId('');
    setConfirmed('');
    setPage(0);
    setApplied({});
  };
  const refresh = () => {
    list.reload();
    pending.reload();
  };
  const close = () => setMode({ kind: 'none' });

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['전체', <Num value={list.data?.total ?? 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>확정 대기</h2>
        <Tiles items={[['미확정 영수증', <Num value={pending.data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>퇴직소득 영수증</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="퇴직 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="확정 여부">
            <Select
              value={confirmed}
              onChange={setConfirmed}
              options={[['true', '확정'], ['false', '미확정']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={() => setMode({ kind: 'create' })}>퇴직금 산정</button>
        </Band>
        <DataTable
          rows={list.data?.items ?? []}
          empty="조회된 영수증이 없습니다."
          onRowClick={(row) => setMode({ kind: 'detail', id: Number(row['retirementPayId']) })}
          columns={[
            { key: 'retirementPayId', label: '퇴직금 ID' },
            { key: 'employeeId', label: '퇴직 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
            { key: 'calculatedAmount', label: '퇴직금 산정액', render: (r) => <Num value={r['calculatedAmount']} /> },
            { key: 'confirmed', label: '확정 여부', render: (r) => <Badge value={r['confirmed'] === true ? '확정' : '미확정'} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      {mode.kind === 'create' && (
        <CreateDrawer role={role} notify={notify} onClose={close} onDone={refresh} />
      )}
      {mode.kind === 'detail' && (
        <DetailDrawer role={role} id={mode.id} onClose={close} onEdit={() => setMode({ kind: 'edit', id: mode.id })} onConfirm={() => setMode({ kind: 'confirm', id: mode.id })} />
      )}
      {mode.kind === 'edit' && (
        <EditDrawer role={role} notify={notify} id={mode.id} onClose={close} onDone={refresh} />
      )}
      {mode.kind === 'confirm' && (
        <ConfirmDrawer role={role} notify={notify} id={mode.id} onClose={close} onDone={refresh} />
      )}
    </div>
  );
}

function CreateDrawer({ role, notify, onClose, onDone }: { role: string; notify: (t: string) => void; onClose: () => void; onDone: () => void }) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [retirementDate, setRetirementDate] = useState('');
  return (
    <Drawer title="퇴직금 산정" onClose={onClose}>
      <Form
        submit="산정"
        onSubmit={async () => {
          if (employeeId === '' || !retirementDate) {
            throw new Error('퇴직 임직원과 퇴직일을 입력하세요.');
          }
          await call('POST', '/retirement-pays', role, { employeeId, retirementDate });
          notify('퇴직금을 산정했습니다.');
          onDone();
          onClose();
        }}
      >
        <Field label="퇴직 임직원" required>
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
        <Field label="퇴직일" required>
          <DateInput value={retirementDate} onChange={setRetirementDate} />
        </Field>
      </Form>
    </Drawer>
  );
}

function DetailDrawer({ role, id, onClose, onEdit, onConfirm }: { role: string; id: number; onClose: () => void; onEdit: () => void; onConfirm: () => void }) {
  const detail = useData<Row>(() => call<Row>('GET', '/retirement-pays/' + id, role), [id]);
  const d = detail.data;
  return (
    <Drawer title="퇴직소득 원천징수영수증" onClose={onClose}>
      {detail.error && <p>{detail.error}</p>}
      {d && (
        <>
          <Pairs
            items={[
              ['퇴직금 ID', String(d['retirementPayId'])],
              ['성명', String(d['employeeName'])],
              ['퇴직일', <DateText value={d['retirementDate']} />],
              ['퇴직금 산정액', <Num value={d['calculatedAmount']} />],
              ['원천징수세액', <Num value={d['withholdingTax']} />],
              ['확정 여부', <Badge value={d['confirmed'] === true ? '확정' : '미확정'} />],
            ]}
          />
          {d['confirmed'] !== true && (
            <Band>
              <button type="button" onClick={onEdit}>수정</button>
              <button type="button" onClick={onConfirm}>확정</button>
            </Band>
          )}
        </>
      )}
    </Drawer>
  );
}

function EditDrawer({ role, notify, id, onClose, onDone }: { role: string; notify: (t: string) => void; id: number; onClose: () => void; onDone: () => void }) {
  const detail = useData<Row>(() => call<Row>('GET', '/retirement-pays/' + id, role), [id]);
  const [retirementDate, setRetirementDate] = useState<string | undefined>(undefined);
  const [calculatedAmount, setCalculatedAmount] = useState<number | string | undefined>(undefined);
  const [withholdingTax, setWithholdingTax] = useState<number | string | undefined>(undefined);
  const d = detail.data;
  return (
    <Drawer title="영수증 내용 수정" onClose={onClose}>
      {d && (
        <Form
          submit="수정"
          onSubmit={async () => {
            const body: Row = {};
            if (retirementDate !== undefined && retirementDate !== '') body['retirementDate'] = retirementDate;
            if (calculatedAmount !== undefined && calculatedAmount !== '') body['calculatedAmount'] = calculatedAmount;
            if (withholdingTax !== undefined && withholdingTax !== '') body['withholdingTax'] = withholdingTax;
            if (Object.keys(body).length === 0) {
              throw new Error('수정할 값을 입력하세요.');
            }
            await call('PATCH', '/retirement-pays/' + id, role, body);
            notify('수정했습니다.');
            onDone();
            onClose();
          }}
        >
          <Field label="퇴직일">
            <DateInput value={retirementDate ?? d['retirementDate']} onChange={setRetirementDate} />
          </Field>
          <Field label="퇴직금 산정액">
            <NumberInput value={calculatedAmount ?? d['calculatedAmount']} onChange={setCalculatedAmount} />
          </Field>
          <Field label="원천징수세액">
            <NumberInput value={withholdingTax ?? d['withholdingTax']} onChange={setWithholdingTax} />
          </Field>
        </Form>
      )}
    </Drawer>
  );
}

function ConfirmDrawer({ role, notify, id, onClose, onDone }: { role: string; notify: (t: string) => void; id: number; onClose: () => void; onDone: () => void }) {
  return (
    <Drawer title="영수증 확정" onClose={onClose}>
      <Form
        submit="확정"
        danger
        note="확정하면 영수증을 수정할 수 없습니다."
        onSubmit={async () => {
          await call('POST', '/retirement-pays/' + id + '/confirm', role, {});
          notify('확정했습니다.');
          onDone();
          onClose();
        }}
      />
    </Drawer>
  );
}
